items.content_full:
(async function () {
console.log("⏳ 正在获取凭证并请求生成链接...");
try {
// 1. 动态获取当前 Access Token
const session = await fetch("/api/auth/session").then((r) => r.json());
if (!session.accessToken) {
throw new Error("无法获取 Token，请确保你已登录 ChatGPT");
}
const token = session.accessToken;
// 2. 请求体 (已强制指定 checkout_ui_mode 为 hosted)
const payload = {
entry_point: "all_plans_pricing_modal",
plan_name: "chatgptplusplan",
billing_details: {
country: "JP",
currency: "JPY"
},
checkout_ui_mode: "hosted",
promo_campaign: {
promo_campaign_id: "plus-1-month-free",
is_coupon_from_query_param: false
}
};
console.log("🚀 发送 checkout 请求...");
// 3. 发送支付创建请求
const res = await fetch(
"chatgpt.com/backend-api/paym…",
{
method: "POST",
headers: {
Authorization: `Bearer ${token}`,
"Content-Type": "application/json"
},
body: JSON.stringify(payload)
}
);
const data = await res.json();
if (!res.ok) {
throw new Error(data.detail || data.message || `HTTP ${res.status}`);
}
console.log("✅ 接口返回原始数据:", data);
// 4. 解析支付链接（优先读取 url，若没有则尝试用 session_id 拼接）
let payUrl = data.url;
if (!payUrl && data.checkout_session_id) {
payUrl = `checkout.stripe.com/c/pay/${data.checkout_session_id}`;
}
// 5. 输出结果
if (payUrl) {
console.clear();
console.log(
"%c✅ 成功生成支付链接：",
"color: #10a37f; font-size: 20px; font-weight: bold;"
);
console.log(
"%c该链接可尝试直接发给他人代付",
"color: #e67e22; font-weight: bold;"
);
console.log("\n" + payUrl);
} else {
console.error("❌ 未能在返回数据中匹配到有效的支付 URL：", data);
}
} catch (e) {
console.error("❌ 执行出错:", e);
}
})();

